/** Extra checks of the status / input-box readers (not in the Swift self-test, which covers the detectors only). */
function extra() {
  const fails = [];
  const eq = (name, got, want) => { if (JSON.stringify(got) !== JSON.stringify(want)) fails.push(`${name}: got ${JSON.stringify(got)} want ${JSON.stringify(want)}`); };
  const byName = Object.fromEntries(fixtures.map((f) => [f.name, f.text]));
  // spinner line while busy
  eq('status busy-30-narrow verb', screen.status(byName['busy-30-narrow']).verb, 'Flibbertigibbeting');
  eq('status busy-30-narrow elapsed', screen.status(byName['busy-30-narrow']).elapsed, '3s');
  eq('status todo thinking', screen.status(byName['busy-28-todo-list-synthetic']).elapsed, null);
  // done line + footer mode / agents
  const box = (inner) => `────────────\n❯ ${inner}\n────────────\n`;
  const s = screen.status(`✻ Cogitated for 2m 47s · done 2:16 AM\n${box('')}  ⏵⏵ auto mode on (shift+tab to cycle) · ← 3 agents`);
  eq('status done', s.done, 'Cogitated for 2m 47s · done 2:16 AM');
  eq('status mode', s.mode, 'auto mode');
  eq('status agents', s.agents, 3);
  const sp = screen.status(`Running 1 shell command…\n· Mustering… (2m 30s · ↓ 9.8k tokens · thinking)\n${box('')}  esc to interrupt`);
  eq('status spinner', [sp.verb, sp.elapsed, sp.tokens, sp.thinking, sp.activity], ['Mustering', '2m 30s', '9.8k', true, 'Running 1 shell command…']);
  eq('status empty', screen.statusIsEmpty(screen.status('hello')), true);
  // typed text vs. the dim suggestion / placeholder (capture-pane -e)
  eq('typedInput plain', screen.typedInput(box('hello')), true);
  eq('typedInput empty', screen.typedInput(box(' ')), false);
  eq('typedInput dim', screen.typedInput(box('\u001b[2mTry "fix lint"\u001b[0m')), false);
  eq('suggestion dim', screen.suggestion(box('\u001b[2m이제 실행해줘\u001b[0m')), '이제 실행해줘');
  eq('suggestion placeholder', screen.suggestion(box('\u001b[2mTry "how do I log an error?"\u001b[0m')), null);
  eq('suggestion typed', screen.suggestion(box('\u001b[0mabc')), null);
  eq('hasInputBox', [screen.hasInputBox(box('')), screen.hasInputBox('no box here')], [true, false]);
  eq('stripANSI', screen.stripANSI('\u001b]0;title\u0007\u001b[1;31mred\u001b[0m\u001b(B'), 'red');
  // the permission prompt's preview and options
  const pr = screen.prompt(byName['permission-cursor-1']);
  eq('prompt preview', pr && pr.preview, 'touch x.txt');
  eq('prompt option 2', pr && pr.options[1], 'Yes, and always allow access to /private/tmp/claude-501/-Users-Junil-Desktop-agent-boa rd-Sources-AgentBridge/fe771f49-c3cb-4c0a-bf29-f3cdaec4 2ae9/scratchpad/fx/work from this project');
  return fails;
}

function run() {
  let failed = 0;
  for (const f of fixtures) {
    const b = screen.busy(f.text), n = screen.needsInput(f.text);
    const sw = screen.isSwitchModelPrompt(f.text);
    const pr = screen.prompt(f.text);
    const e = f.prompt;
    const promptOK = e ? (!!pr && pr.title === e.title && pr.options.length === e.options && pr.cursor === e.cursor && pr.numbered === e.numbered) : pr === null;
    const ov = screen.overlay(f.text);
    const ok = b === f.busy && n === f.needsInput && sw === f.switchModel && promptOK && ov === f.overlay;
    if (pr) console.log(`   prompt: title=${JSON.stringify(pr.title)} detail=${JSON.stringify(pr.detail || '')} preview=${pr.preview ? pr.preview.split('\n').length : 0} lines options=${JSON.stringify(pr.options)} cursor=${pr.cursor} numbered=${pr.numbered}`);
    if (!ok) failed += 1;
    console.log(`${ok ? 'PASS' : 'FAIL'} ${f.name}: busy=${b} (want ${f.busy}) needsInput=${n} (want ${f.needsInput}) switchModel=${sw} (want ${f.switchModel}) prompt=${promptOK ? 'ok' : 'MISMATCH'} overlay=${ov} (want ${f.overlay})`);
  }
  console.log(failed === 0 ? `ALL ${fixtures.length} PASSED` : `${failed} FAILED`);
  const fails = extra();
  for (const x of fails) console.log('FAIL ' + x);
  console.log(fails.length === 0 ? 'status/input checks PASSED' : `${fails.length} status/input checks FAILED`);
  return failed === 0 && fails.length === 0 ? 0 : 1;
}

if (require.main === module) process.exit(run());
module.exports = { fixtures, run };
